H,W=I.shape
def solve(inp, marker):
    g=np.array(inp); H,W=g.shape
    out=g.copy()
    mks=[(r,c) for r in range(H) for c in range(W) if g[r,c]==marker]
    dirs=[(0,1),(1,0),(1,1),(1,-1)]
    for dr,dc in dirs:
        # for each line, find consecutive marker pairs and fill between
        from collections import defaultdict
        lines=defaultdict(list)
        for r,c in mks:
            if dc==1: key=(r, 'r') if dr==0 else (r-c,'d1') if dr==1 else (r+c,'d2')
            elif dr==1 and dc==0: key=(c,'c')
            lines[key].append((r,c))
        for k,pts in lines.items():
            pts.sort()
            for (r1,c1),(r2,c2) in zip(pts,pts[1:]):
                steps=(r2-r1)//dr if dr else (c2-c1)//dc
                for s in range(1,steps):
                    r,c=r1+dr*s, c1+dc*s
                    if g[r,c]!=marker: out[r,c]=3
    return out
