def solve_rc(inp, marker):
    g=np.array(inp); H,W=g.shape
    out=g.copy()
    mks=[(r,c) for r in range(H) for c in range(W) if g[r,c]==marker]
    for dr,dc in [(0,1),(1,0)]:
        from collections import defaultdict
        lines=defaultdict(list)
        for r,c in mks:
            key=r if dr==0 else c
            lines[key].append((r,c) if dr==0 else (r,c))
        for k,pts in lines.items():
            pts.sort()
            for (r1,c1),(r2,c2) in zip(pts,pts[1:]):
                steps=(r2-r1) if dr else (c2-c1)
                for s in range(1,steps):
                    r,c=(r1,c1+s) if dr==0 else (r1+s,c1)
                    if g[r,c]!=marker: out[r,c]=3
    return out
